13	import org.junit.jupiter.api.TestInfo;
14	
15	/**
16	 * Black-Box 통합 테스트 공용 지원 유틸리티 (template-render v2 생성).
17	 *
18	 * <p>내부 애플리케이션 클래스를 import 하지 않는다. 순수 HTTP(RestAssured) + 직접 JDBC 만 사용한다.
19	 * 접속 정보 기본값은 prestep 환경 분석 산출물(support-config.json)에서 주입되며,
20	 * 시스템 프로퍼티로 외부 재정의 가능하다. 인증 헬퍼는 SUT마다 달라 여기 두지 않고
21	 * 각 테스트 클래스에 인증 카탈로그 패턴으로 렌더된다.</p>
22	 */
23	public final class BlackBoxSupport {
24	
25	    private BlackBoxSupport() {
26	    }
27	
28	    public static final String BASE_URL =
29	            System.getProperty("test.server.url", "@@SERVER_URL@@");
30	    public static final String WIREMOCK_URL =
31	            System.getProperty("test.wiremock.url", "@@WIREMOCK_URL@@");
32	
33	    private static final String DB_URL =
34	            System.getProperty("test.db.url", "@@DB_URL@@");
35	    private static final String DB_USER =
36	            System.getProperty("test.db.user", "@@DB_USER@@");
37	    private static final String DB_PASSWORD =
38	            System.getProperty("test.db.password", "@@DB_PASSWORD@@");
39	
40	    /** 병렬 안전: 매 호출마다 독립 Connection. */
41	    public static Connection getDbConnection() throws Exception {
42	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
43	    }
44	
45	    /** 메서드명 기반 결정적 고유 ID (재실행 시 동일값). */
46	    public static String testId(TestInfo info) {
47	        return String.format("T%09d",
48	                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
49	    }
50	
51	    /**
52	     * testId → 결정적 숫자 seq. 실 데이터와 겹치지 않도록 오프셋을 더한다.
53	     * 오프셋 기본값은 support-config.json 의 idOffset 로 주입된다 — 대상 DB PK가
54	     * 32-bit INT 이면 32비트 한계 내(예: 1_000_000_000)로 설정할 것.
55	     */
56	    public static long testSeq(TestInfo info) {
57	        return @@ID_OFFSET@@L
58	                + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000L);
59	    }
60	
61	    // ---- SQL 실행 ----------------------------------------------------------
62	
63	    public static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
64	        try (InputStream is = BlackBoxSupport.class.getClassLoader().getResourceAsStream(resourcePath)) {
65	            if (is == null) {
66	                throw new IllegalStateException("SQL resource not found: " + resourcePath);
67	            }
68	            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
69	            for (Map.Entry<String, String> e : params.entrySet()) {
70	                sql = sql.replace("${" + e.getKey() + "}", e.getValue());
71	            }
72	            executeSqlScript(sql);
73	        } catch (RuntimeException e) {
74	            throw e;
75	        } catch (Exception e) {
76	            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
77	        }
78	    }
79	
80	    public static void executeSqlScript(String sql) {
81	        try (Connection conn = getDbConnection(); Statement stmt = conn.createStatement()) {
82	            StringBuilder current = new StringBuilder();
83	            for (String rawLine : sql.split("\n")) {
84	                String line = rawLine.trim();
85	                if (line.isEmpty() || line.startsWith("--")) {
86	                    continue;
87	                }
88	                current.append(line).append(' ');
89	                if (line.endsWith(";")) {
90	                    String stmtSql = current.toString().trim();
91	                    stmtSql = stmtSql.substring(0, stmtSql.length() - 1);
92	                    if (!stmtSql.isEmpty()) {
93	                        stmt.execute(stmtSql);
94	                    }
95	                    current.setLength(0);
96	                }
97	            }
98	            String tail = current.toString().trim();
99	            if (!tail.isEmpty()) {
100	                stmt.execute(tail);
101	            }
102	        } catch (Exception e) {
103	            throw new RuntimeException("SQL script execution failed", e);
104	        }
105	    }
106	
107	    /** 단일 스칼라 조회(첫 컬럼). 없으면 null. */
108	    public static String queryScalar(String sql, Object... args) {
109	        try (Connection conn = getDbConnection();
110	             PreparedStatement ps = conn.prepareStatement(sql)) {
111	            for (int i = 0; i < args.length; i++) {
112	                ps.setObject(i + 1, args[i]);
113	            }
114	            try (ResultSet rs = ps.executeQuery()) {
115	                if (rs.next()) {
116	                    return rs.getString(1);
117	                }
118	                return null;
119	            }
120	        } catch (Exception e) {
121	            throw new RuntimeException("queryScalar failed: " + sql, e);
